#!/bin/sh
# Seed the lab database, then create the ETL account with the password generated by
# lab/setup_lab.py (mounted per host, never stored in the repository).
set -eu
mariadb < /opt/lab/seed.sql
pw="$(cat /etc/wheelhouse-lab/etl_password)"
mariadb <<SQL
CREATE USER IF NOT EXISTS 'etl'@'%' IDENTIFIED BY '${pw}';
ALTER USER 'etl'@'%' IDENTIFIED BY '${pw}';
GRANT SELECT ON app.orders TO 'etl'@'%';
GRANT INSERT, UPDATE, DELETE ON app.orders_daily TO 'etl'@'%';
FLUSH PRIVILEGES;
SQL
